def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n == 1:
        return 'C'

    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1

    # Strongly cooperative opponent: maintain mutual cooperation.
    if opp_c >= n - 2 and opp_last == 'C':
        return 'C'

    # Near end, avoid being exploited by mostly-cooperative opponents.
    if n >= 94:
        if opp_c * 3 >= n * 2 and opp_last == 'C':
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'

    # Very defective opponent: resist, but occasionally test recovery.
    if opp_c <= 2 and n >= 8:
        if n < 90 and rng.randint(0, 5) == 0:
            return 'C'
        return 'D'

    # Detect opponent's current streak.
    same_count = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            same_count += 1
        else:
            break

    # After a long defection streak, test cooperation sometimes to unlock CC.
    if opp_last == 'D' and same_count >= 4:
        if n < 92 and rng.randint(0, 2) == 0:
            return 'C'
        return 'D'

    # Opponent cooperating for a while: mostly cooperate, rarely probe.
    if opp_last == 'C' and same_count >= 5:
        if n < 88 and rng.randint(0, 11) == 0:
            return 'D'
        return 'C'

    # After our own defection followed by opponent cooperation, return to C.
    if opp_last == 'C':
        if my_last == 'D':
            return 'C'
        return 'C'

    # Opponent just defected.
    if opp_last == 'D':
        if my_last == 'C':
            return 'D'
        if n < 90 and rng.randint(0, 5) == 0:
            return 'C'
        return 'D'

    return 'C'
